"""Fail-closed readiness gate for physical OpenIPC end-to-end validation."""
from copy import deepcopy

def hardware_e2e_readiness(device,network_evidence,credentials_present=False,host_key_accepted=False,firmware=None):
 device=dict(device or {});identity=dict(device.get('openipcIdentity') or {});host=str(device.get('host') or '');evidence=network_evidence or {};observed=next((x for x in evidence.get('devices',[]) if x.get('host')==host),{});firmware=dict(firmware or {});artifact=dict(firmware.get('artifact') or {});plan=dict(firmware.get('plan') or {})
 checks={'deviceSelected':bool(device.get('id') and host),'openipcVerified':identity.get('verified') is True and bool(identity.get('evidence')),'hardwareIdentityObserved':bool(identity.get('platform') and identity.get('sensor')),'networkRouteObserved':bool((evidence.get('summary') or {}).get('safeRoutes',0)>0),'deviceReachableObserved':observed.get('reachable') is True,'firmwareArtifactVerified':artifact.get('verified') is True and bool(artifact.get('sha256')) and int(artifact.get('size') or 0)>0,'executionPlanReady':plan.get('ready') is True and plan.get('deviceId')==device.get('id'),'credentialsPresent':credentials_present is True,'hostKeyAccepted':host_key_accepted is True}
 ready=all(checks.values());missing=[name for name,value in checks.items() if not value]
 return {'ready':ready,'checks':deepcopy(checks),'missing':missing,'deviceId':device.get('id') or None,'host':host or None,'platform':identity.get('platform') or None,'sensor':identity.get('sensor') or None,'firmware':identity.get('firmware') or None,'artifact':{'sha256':artifact.get('sha256') or None,'size':artifact.get('size') or None,'build':artifact.get('build') or None},'profile':plan.get('profile') or None,'mode':plan.get('mode') or None}
